CREATE TABLE sources(id text PRIMARY KEY, platform text NOT NULL, name text NOT NULL, config jsonb NOT NULL DEFAULT '{}', enabled boolean NOT NULL DEFAULT false);
CREATE TABLE source_items(id text PRIMARY KEY, source_id text NOT NULL REFERENCES sources(id), canonical_url text NOT NULL, title text NOT NULL, excerpt text, published_at timestamptz, fetched_at timestamptz NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', UNIQUE(source_id,canonical_url));
CREATE TABLE trend_signals(id text PRIMARY KEY, source_id text NOT NULL REFERENCES sources(id), topic text NOT NULL, region text NOT NULL, observed_at timestamptz NOT NULL, metrics jsonb NOT NULL DEFAULT '{}');
CREATE TABLE story_clusters(id text PRIMARY KEY, title text NOT NULL, first_seen timestamptz NOT NULL, last_seen timestamptz NOT NULL, attention numeric CHECK(attention BETWEEN 0 AND 100), relevance numeric CHECK(relevance BETWEEN 0 AND 100));
CREATE TABLE cluster_items(cluster_id text REFERENCES story_clusters(id), item_id text REFERENCES source_items(id), PRIMARY KEY(cluster_id,item_id));
CREATE TABLE claims(id text PRIMARY KEY, cluster_id text NOT NULL REFERENCES story_clusters(id), exact_text text NOT NULL, priority numeric NOT NULL CHECK(priority BETWEEN 0 AND 100), sensitive boolean NOT NULL DEFAULT false);
CREATE TABLE evidence(id text PRIMARY KEY, claim_id text NOT NULL REFERENCES claims(id), url text NOT NULL, publisher text NOT NULL, independence_group text, excerpt text NOT NULL, source_tier integer NOT NULL CHECK(source_tier BETWEEN 1 AND 4), relation text NOT NULL CHECK(relation IN ('supports','contradicts','contextualizes')), retrieved_at timestamptz NOT NULL, UNIQUE(id,claim_id));
CREATE TABLE verifications(id text PRIMARY KEY, claim_id text NOT NULL REFERENCES claims(id), revision integer NOT NULL CHECK(revision>0), verdict text NOT NULL CHECK(verdict IN ('CONFIRMAT','CORECT, DAR LIPSEȘTE CONTEXT','CONTEXT FALS','CONTESTAT','NECONFIRMAT','FALS','NU ESTE O AFIRMAȚIE VERIFICABILĂ')), explanation text NOT NULL, checked_at timestamptz NOT NULL, review_status text NOT NULL CHECK(review_status IN ('proposed','policy_accepted','operator_accepted')), UNIQUE(claim_id,revision), UNIQUE(id,claim_id));
CREATE TABLE verification_evidence(verification_id text NOT NULL, claim_id text NOT NULL, evidence_id text NOT NULL, PRIMARY KEY(verification_id,evidence_id), FOREIGN KEY(verification_id,claim_id) REFERENCES verifications(id,claim_id), FOREIGN KEY(evidence_id,claim_id) REFERENCES evidence(id,claim_id));
CREATE TABLE transcripts(id text PRIMARY KEY, source_item_id text NOT NULL REFERENCES source_items(id), provider text NOT NULL, language text NOT NULL, body text NOT NULL, segments jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL);
CREATE TABLE media_assets(id text PRIMARY KEY, source_url text NOT NULL, asset_path text NOT NULL, credit text NOT NULL, rights_status text NOT NULL CHECK(rights_status IN ('unknown','approved','rejected')), rights_basis text NOT NULL, width integer NOT NULL CHECK(width>0), height integer NOT NULL CHECK(height>0), checksum text, metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE editions(id text PRIMARY KEY, edition_date date NOT NULL, timezone text NOT NULL DEFAULT 'Europe/Bucharest', revision integer NOT NULL DEFAULT 1 CHECK(revision>0), mode text NOT NULL CHECK(mode IN ('fixture','live')), status text NOT NULL CHECK(status IN ('draft','validated','rendered','ready','blocked')), pdf_path text, pdf_checksum text, page_count integer CHECK(page_count BETWEEN 1 AND 4), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(edition_date,revision,mode), CHECK(status<>'ready' OR (pdf_path IS NOT NULL AND pdf_checksum IS NOT NULL AND page_count IS NOT NULL)));
CREATE TABLE edition_stories(id text PRIMARY KEY, edition_id text NOT NULL REFERENCES editions(id), cluster_id text NOT NULL REFERENCES story_clusters(id), photo_id text NOT NULL REFERENCES media_assets(id), section text NOT NULL, rank integer NOT NULL, article_snapshot jsonb NOT NULL, UNIQUE(edition_id,cluster_id), UNIQUE(edition_id,rank));
CREATE TABLE pipeline_runs(id text PRIMARY KEY, idempotency_key text NOT NULL UNIQUE, edition_id text REFERENCES editions(id), state text NOT NULL CHECK(state IN ('pending','running','succeeded','failed')), started_at timestamptz, finished_at timestamptz);
CREATE TABLE stage_runs(id text PRIMARY KEY, run_id text NOT NULL REFERENCES pipeline_runs(id), stage text NOT NULL, state text NOT NULL CHECK(state IN ('pending','running','succeeded','failed','skipped')), attempt integer NOT NULL DEFAULT 0, lease_until timestamptz, output jsonb, error jsonb, UNIQUE(run_id,stage));
CREATE TABLE usage_ledger(id text PRIMARY KEY, run_id text NOT NULL REFERENCES pipeline_runs(id), provider text NOT NULL, operation text NOT NULL, request_id text NOT NULL, attempt integer NOT NULL, units jsonb NOT NULL, cost_estimate numeric CHECK(cost_estimate>=0), currency text NOT NULL, success boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,request_id,attempt));
CREATE TABLE print_jobs(id text PRIMARY KEY, edition_id text NOT NULL REFERENCES editions(id), request_id text NOT NULL, printer text NOT NULL, pdf_checksum text NOT NULL, state text NOT NULL CHECK(state IN ('pending','claimed','submitting','submitted','completed','failed','unknown')), cups_job_id text, requested_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, error text, UNIQUE(edition_id,request_id));
CREATE TABLE audit_events(id text PRIMARY KEY, entity_type text NOT NULL, entity_id text NOT NULL, action text NOT NULL, actor text NOT NULL, reason text NOT NULL, before_value jsonb, after_value jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX source_items_published_idx ON source_items(published_at);
CREATE INDEX evidence_claim_idx ON evidence(claim_id);
CREATE INDEX stages_pending_idx ON stage_runs(state,lease_until);
